CREATE TEMP TABLE tmp_daily_produksi_seed AS
SELECT
  r.report_date,
  'Pagi'::TEXT AS shift,
  r.no_mesin,
  CASE
    WHEN UPPER(r.kategori_part_raw) IN ('SMALL', 'MEDIUM', 'BIG', 'SA') THEN UPPER(r.kategori_part_raw)
    WHEN p.kategori IN ('SMALL', 'MEDIUM', 'BIG', 'SA') THEN p.kategori
    ELSE 'MEDIUM'
  END AS kategori_part,
  r.nama_part,
  r.total_output,
  r.short_shot,
  r.lipat,
  r.burry,
  r.bending,
  r.dirty,
  r.kontaminasi,
  r.filter_bolong_rusak,
  r.shinning,
  r.silver,
  r.flow_mark,
  r.burn_mark,
  r.sink_mark,
  r.ejector_mark,
  r.gas_mark,
  r.crack,
  r.gap,
  r.dented,
  r.scratch,
  r.flash,
  r.double_inject,
  r.bubble,
  r.gate_long,
  r.gate_hole,
  r.over_cut,
  r.under_cut,
  r.black_dot,
  r.deform,
  r.weld_line,
  r.start_up_setting_alarm,
  (r.short_shot + r.lipat + r.burry + r.bending + r.dirty + r.kontaminasi + r.filter_bolong_rusak + r.shinning + r.silver + r.flow_mark + r.burn_mark + r.sink_mark + r.ejector_mark + r.gas_mark + r.crack + r.gap + r.dented + r.scratch + r.flash + r.double_inject + r.bubble + r.gate_long + r.gate_hole + r.over_cut + r.under_cut + r.black_dot + r.deform + r.weld_line + r.start_up_setting_alarm) AS total_ng,
  GREATEST(r.total_output - (r.short_shot + r.lipat + r.burry + r.bending + r.dirty + r.kontaminasi + r.filter_bolong_rusak + r.shinning + r.silver + r.flow_mark + r.burn_mark + r.sink_mark + r.ejector_mark + r.gas_mark + r.crack + r.gap + r.dented + r.scratch + r.flash + r.double_inject + r.bubble + r.gate_long + r.gate_hole + r.over_cut + r.under_cut + r.black_dot + r.deform + r.weld_line + r.start_up_setting_alarm), 0) AS total_ok
FROM tmp_daily_produksi_raw r
LEFT JOIN public.parts p
  ON UPPER(TRIM(p.nama_part)) = UPPER(TRIM(r.nama_part));

INSERT INTO public.production_reports (
  report_date,
  shift,
  no_mesin,
  kategori_part,
  nama_part,
  total_output,
  total_ok,
  total_ng,
  created_by
)
SELECT
  report_date,
  shift,
  no_mesin,
  kategori_part,
  nama_part,
  total_output,
  total_ok,
  total_ng,
  NULL
FROM tmp_daily_produksi_seed
ON CONFLICT (report_date, shift, no_mesin, nama_part) DO UPDATE
SET
  kategori_part = EXCLUDED.kategori_part,
  total_output = EXCLUDED.total_output,
  total_ok = EXCLUDED.total_ok,
  total_ng = EXCLUDED.total_ng,
  updated_at = now();

CREATE TEMP TABLE tmp_daily_produksi_report_ids AS
SELECT
  pr.id AS report_id,
  t.short_shot,
  t.lipat,
  t.burry,
  t.bending,
  t.dirty,
  t.kontaminasi,
  t.filter_bolong_rusak,
  t.shinning,
  t.silver,
  t.flow_mark,
  t.burn_mark,
  t.sink_mark,
  t.ejector_mark,
  t.gas_mark,
  t.crack,
  t.gap,
  t.dented,
  t.scratch,
  t.flash,
  t.double_inject,
  t.bubble,
  t.gate_long,
  t.gate_hole,
  t.over_cut,
  t.under_cut,
  t.black_dot,
  t.deform,
  t.weld_line,
  t.start_up_setting_alarm
FROM tmp_daily_produksi_seed t
JOIN public.production_reports pr
  ON pr.report_date = t.report_date
 AND pr.shift = t.shift
 AND pr.no_mesin = t.no_mesin
 AND pr.nama_part = t.nama_part;

DELETE FROM public.defect_details dd
USING tmp_daily_produksi_report_ids t
WHERE dd.report_id = t.report_id;

INSERT INTO public.defect_details (
  report_id,
  short_shot,
  lipat,
