  gate_long,
  gate_hole,
  over_cut,
  under_cut,
  black_dot,
  deform,
  weld_line,
  start_up_setting_alarm,
  extra_defects
)
SELECT
  report_id,
  short_shot,
  lipat,
  burry,
  bending,
  dirty,
  kontaminasi,
  filter_bolong_rusak,
  shinning,
  silver,
  flow_mark,
  burn_mark,
  sink_mark,
  ejector_mark,
  gas_mark,
  crack,
  gap,
  dented,
  scratch,
  flash,
  double_inject,
  bubble,
  gate_long,
  gate_hole,
  over_cut,
  under_cut,
  black_dot,
  deform,
  weld_line,
  start_up_setting_alarm,
  '{}'::jsonb
FROM tmp_daily_produksi_report_ids;

COMMIT;
